\title{The Unramified Obstruction Equals the Descent Obstruction\\
for Rationally Connected Varieties over $p$-adic Function Fields}
\author{Aristotle}
\date{2026-06-29}

\begin{document}
\maketitle

\begin{abstract}
Let $K$ be the function field of a smooth projective geometrically integral curve over a
$p$-adic field, and let $X$ be a smooth, proper, geometrically integral, rationally
connected $K$-variety. We study two obstructions to the existence of a rational point on
$X$: the \emph{descent obstruction}, built from torsors under linear algebraic groups, and
the \emph{unramified obstruction} attached to the degree-three unramified cohomology
$H^3_{nr}(X, \QZ(2))$. Because the cohomological dimension of $K$ is exactly three --- one
above that of the $p$-adic base --- the degree-three unramified cohomology plays the role
over $K$ that the Brauer group $H^2_{nr}(X,\QZ(1))$ plays over a number field. We prove
that the structural core of the assertion
$X(\AK)^{H^3_{nr}} = X(\AK)^{\mathrm{descent}}$
is a soft consequence of one fact: both obstructions are left orthogonals under a single
reciprocity pairing between adelic points and cohomology classes. We isolate this core,
prove it in full generality, and reduce the conjecture to a single inclusion of cohomology
subgroups. We certify non-vacuity with an explicit finite model in which the descent
classes are properly contained in the unramified classes yet the obstruction sets are equal
and form a proper, nonempty subset of the ambient space.
\end{abstract}

\section{Introduction}

\subsection{The local--global gap}
Let $K$ be a field with a distinguished family of completions $K_v$. A smooth proper
$K$-variety $X$ has a rational point only if it has points everywhere locally, i.e.\ an
\emph{adelic point} in the restricted product $X(\AK) = \prod'_v X(K_v)$. The converse
fails, and quantifying this failure is the business of \emph{obstructions}, which remove
from $X(\AK)$ the adelic points incompatible with a global point.

\subsection{Obstructions as orthogonals}
The prototype is the \textbf{Brauer--Manin obstruction}. Class field theory furnishes, for
each Brauer class $b \in \Br(X) = H^2_{nr}(X, \QZ(1))$ and each adelic point $s$, a
reciprocity value $\langle s, b\rangle \in \QZ$ vanishing whenever $s$ comes from a rational
point. The surviving set
\[
  X(\AK)^{\Br} = \{\, s \in X(\AK) : \langle s, b\rangle = 0 \ \forall b \in \Br(X) \,\}
\]
is the \textbf{left orthogonal} of $\Br(X)$. Its refinements --- the \textbf{descent
obstruction} (torsors under linear algebraic groups) and the \textbf{\'etale--Brauer
obstruction} --- are the same construction with a larger supply of classes. Over number
fields, \textbf{Colliot-Th\'el\`ene's conjecture} asserts that for rationally connected $X$
the Brauer--Manin obstruction is the only obstruction.

\subsection{The $p$-adic-function-field analogue}
Let $K$ be the function field of a smooth projective geometrically integral curve over a
$p$-adic field $k$. The cohomological dimension satisfies
\[
  \cd(K) = \cd(k) + 1 = 2 + 1 = 3.
\]
This invariant dictates which cohomology controls rational points. Over number fields the
relevant unramified cohomology sits in degree two; over $K$ it is pushed up by one. The
correct analogue of the Brauer group is the degree-three unramified cohomology
$H^3_{nr}(X, \QZ(2))$, with corresponding \textbf{unramified obstruction}
$X(\AK)^{H^3_{nr}}$.

\medskip
\noindent\textbf{The conjecture.} \emph{For $X$ smooth, proper, geometrically integral and
rationally connected over $K$,}
\[
  X(\AK)^{H^3_{nr}} \;=\; X(\AK)^{\mathrm{descent}}.
\]

\subsection{Results}
We split the conjecture into a \emph{structural layer} (proved here in full generality) and
an \emph{arithmetic layer} (one inclusion of cohomology subgroups). The structural layer
shows the equality of obstruction sets is equivalent to an equality of closed cohomology
subgroups and is forced by $\Hunr \subseteq \clB(\Hdesc)$. We also exhibit a finite model
proving non-vacuity.

\section{The abstract obstruction datum}

\begin{definition}[Pairing datum]
A \emph{pairing datum} consists of abelian groups $S$ (adelic points), $B$ (cohomology
classes), $C$ (values), and a biadditive map $\langle\,\cdot\,,\,\cdot\,\rangle : S \times B
\to C$. In the arithmetic setting $C = \QZ$ and the pairing is the reciprocity pairing.
\end{definition}

\begin{definition}[Orthogonals]
For $H \subseteq B$ and $T \subseteq S$,
\[
  H^{\perp} = \{ s \in S : \langle s, b\rangle = 0 \ \forall b \in H \},
  \qquad
  T^{\perp} = \{ b \in B : \langle s, b\rangle = 0 \ \forall s \in T \}.
\]
The \emph{obstruction set} cut out by $H$ is $H^{\perp} \subseteq S$.
\end{definition}

\begin{definition}[Closure]
Set $\clB(H) = (H^{\perp})^{\perp} \subseteq B$.
\end{definition}

\begin{definition}[Obstruction datum]
An \emph{obstruction datum} is a pairing datum with families $\Hdesc, \Hunr \subseteq B$
satisfying $\Hdesc \subseteq \Hunr \subseteq \clB(\Hdesc)$. Its descent and unramified
obstructions are $\Hdesc^{\perp}$ and $\Hunr^{\perp}$.
\end{definition}

\begin{theorem}[Antitone Galois connection]\label{thm:galois}
For all $H \subseteq B$ and $T \subseteq S$,
\[
  H \subseteq T^{\perp} \iff T \subseteq H^{\perp}.
\]
\end{theorem}
\begin{proof}
Both sides unwind to $\langle s, b\rangle = 0$ for all $s \in T$, $b \in H$.
\end{proof}

\begin{proposition}[Closure operator]\label{prop:closure}
The map $\clB = ((-)^{\perp})^{\perp}$ on subsets of $B$ is extensive ($H \subseteq \clB H$),
monotone, and idempotent ($\clB(\clB H) = \clB H$).
\end{proposition}
\begin{proof}
Extensivity and monotonicity are formal from Theorem~\ref{thm:galois}. The antitone Galois
pair satisfies $\phi = \phi\psi\phi$, giving the identity $H^{\perp} = (\clB H)^{\perp}$;
taking $\perp$ yields idempotence.
\end{proof}

\begin{theorem}[Closure invariance]\label{thm:inv}
For every $H \subseteq B$, $H^{\perp} = (\clB H)^{\perp}$, and more generally
$H^{\perp} = \langle H\rangle^{\perp}$ where $\langle H\rangle$ is the generated subgroup.
\end{theorem}
\begin{proof}
The first identity appears in the proof of Proposition~\ref{prop:closure}. For the second,
$H \subseteq \langle H\rangle$ gives $\langle H\rangle^{\perp} \subseteq H^{\perp}$; if
$s \in H^{\perp}$ then $\langle s, -\rangle$ is a homomorphism vanishing on $H$, hence on
$\langle H\rangle$.
\end{proof}

\begin{theorem}[Equality criterion]\label{thm:crit}
For $H_1, H_2 \subseteq B$, $\ H_1^{\perp} = H_2^{\perp} \iff \clB(H_1) = \clB(H_2)$.
\end{theorem}
\begin{proof}
($\Leftarrow$) $H_1^{\perp} = (\clB H_1)^{\perp} = (\clB H_2)^{\perp} = H_2^{\perp}$ by
Theorem~\ref{thm:inv}. ($\Rightarrow$) Apply $\perp$ to $H_1^{\perp} = H_2^{\perp}$.
\end{proof}

\begin{theorem}[Sandwich comparison]\label{thm:sandwich}
If $\Hdesc \subseteq \Hunr \subseteq \clB(\Hdesc)$ then $\Hunr^{\perp} = \Hdesc^{\perp}$.
\end{theorem}
\begin{proof}
Applying the monotone, idempotent closure operator across the sandwich,
\[
  \clB(\Hdesc) \subseteq \clB(\Hunr) \subseteq \clB(\clB(\Hdesc)) = \clB(\Hdesc),
\]
so $\clB(\Hunr) = \clB(\Hdesc)$. Conclude by Theorem~\ref{thm:crit}.
\end{proof}

\begin{corollary}[Unramified equals descent]
For a smooth proper rationally connected variety $X$ over a $p$-adic function field $K$,
assume the descent classes are unramified and the unramified classes lie in the closure of
the descent classes. Then $X(\AK)^{H^3_{nr}} = X(\AK)^{\mathrm{descent}}$.
\end{corollary}

The entire remaining content is the inclusion $\Hunr \subseteq \clB(\Hdesc)$, which is where
rational connectedness and $\cd(K) = 3$ enter.

\section{Non-vacuity: an explicit finite model}

\begin{construction}\label{con:model}
Take $S = B = C = \mathbb{Z}/4\mathbb{Z}$ with pairing $\langle s, b\rangle = (2s)\cdot b
\pmod 4$. Set $\Hdesc = \{1\}$ and $\Hunr = \{1, 2\}$.
\end{construction}

\begin{proposition}
In Construction~\ref{con:model}: (i) $\Hdesc \subsetneq \Hunr$; (ii) the sandwich
$\Hdesc \subseteq \Hunr \subseteq \clB(\Hdesc)$ holds; (iii) the common obstruction set is
$\{0,2\}$, a proper nonempty subgroup of $\mathbb{Z}/4$; (iv) $\Hunr^{\perp} = \Hdesc^{\perp}$.
Hence Theorem~\ref{thm:sandwich} is non-vacuous.
\end{proposition}
\begin{proof}
(i) $2 \in \Hunr \setminus \Hdesc$. (ii) $1$ generates $\mathbb{Z}/4$, so $2 = 1+1 \in
\langle\{1\}\rangle \subseteq \clB(\{1\})$ by Theorem~\ref{thm:inv} and extensivity; thus
$\Hunr \subseteq \clB(\Hdesc)$. (iii) $\Hdesc^{\perp} = \{ s : 2s = 0 \} = \{0,2\}$, which
contains $0$ but not $1$. (iv) By Theorem~\ref{thm:sandwich}, since the sandwich holds.
The kernel of the pairing is nontrivial, so the obstruction is $\{0,2\}$, not $\{0\}$ ---
a nondegenerate witness.
\end{proof}

\section{Algorithms}

The theory is computable on finite data. The orthogonal $H^{\perp}$ is computed by
filtering $S$ for elements annihilating every class in $H$, in $O(|S|\cdot|H|)$ pairing
evaluations. The closure $\clB(H) = (H^{\perp})^{\perp}$ is two such computations; closed
sets are the fixed points $\clB(H) = H$. To certify $\Hunr^{\perp} = \Hdesc^{\perp}$ one
checks the sandwich and invokes Theorem~\ref{thm:sandwich}, replacing an element-by-element
comparison of orthogonals with a comparison of closures.

\section{Applications and discussion}

\textbf{One closure operator for the whole tower.} Every obstruction in the Brauer--Manin
tower is the orthogonal of a family of cohomology classes; two coincide iff their families
have equal closure. A refinement is strictly stronger only if its classes escape the
closure of the smaller family. Over a $p$-adic function field $\cd(K) = 3$ is the ceiling
at which degree-three unramified cohomology can still absorb new classes, predicting the
tower collapses to a single locus.

\medskip
\textbf{Saturation and the only-obstruction property.} ``The unramified obstruction is the
only obstruction'' becomes the internal condition that the unramified classes are
\emph{saturated}: equal to their own double orthogonal. This converts a Diophantine
existence statement into a structural, finite-type condition.

\medskip
\textbf{Scope.} The structural theory is unconditional; it reduces the conjecture to the
single inclusion $\Hunr \subseteq \clB(\Hdesc)$, localizing all difficulty in one place.

\section{Future directions}

\textbf{One closure operator governs every refinement.} For a fixed smooth proper
rationally connected variety over a $p$-adic function field, the descent, \'etale--Brauer,
and unramified $H^3_{nr}(-, \QZ(2))$ obstructions should all arise as the orthogonal of the
same closed subgroup; the tower collapses to a single locus.

\medskip
\textbf{Saturation criterion.} The unramified obstruction is the only obstruction iff the
unramified classes are saturated.

\medskip
\textbf{Strict refinements.} Identify the mechanism by which classes escape the closure,
the source of any genuine strict refinement.

\section{Conclusion}

The assertion $X(\AK)^{H^3_{nr}} = X(\AK)^{\mathrm{descent}}$ rests on a structural
skeleton: obstructions are left orthogonals under a reciprocity pairing, the orthogonality
operators form an antitone Galois connection, the double orthogonal is a closure operator,
and obstruction sets agree exactly when the closures of their class families agree. The
sandwich inclusion forces the equality of two infinite sets of adelic points with no
further analysis, and a finite model certifies non-vacuity. All genuine arithmetic content
is concentrated in one inclusion of cohomology subgroups.

\end{document}

