function LEFT_ORTHOGONAL(S, H, pairing):
    return { s in S : pairing(s,b) = 0 for all b in H }

function RIGHT_ORTHOGONAL(B, T, pairing):
    return { b in B : pairing(s,b) = 0 for all s in T }

function CLOSURE(S, B, H, pairing):
    P <- LEFT_ORTHOGONAL(S, H, pairing)
    return RIGHT_ORTHOGONAL(B, P, pairing)

